BEGIN;
SET LOCAL search_path = public;

WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (167::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2025-12-11T00:00:00+00:00'::TIMESTAMPTZ, 'f9279d1a242a5ddcdac80835cde73218c574fb6cc3f513180ee51d91b1fc2a4d'::TEXT, ARRAY[498]::BIGINT[]),
    (167::BIGINT, 'Es una clase super entretenida y relajante, la profe es muy profunda y le enseña a uno mucho sobre la vida en general, no solo sobre la materia.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-20T00:00:00+00:00'::TIMESTAMPTZ, '409ce0053f536e40a56481ebc23a117d6c9622d33372989851b7668a480d5545'::TEXT, ARRAY[498]::BIGINT[]),
    (167::BIGINT, 'Teatro es más una clase para que vida que una clase convencional. La profe es muy vacilona y da lecciones de vida. Al principio dudaba si meterlo por ser introvertido, pero hay que salir de esa zona de confort. Se hacen amistades y se enfrentan miedos. No lo piense y METALO de una'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2023-06-19T00:00:00+00:00'::TIMESTAMPTZ, '251f5135d1a3a6b7715c311f8e7e00867934f85daf170f7e059198d86f4fcf08'::TEXT, ARRAY[498]::BIGINT[]),
    (167::BIGINT, 'Es de las mejores profes que he tenido, es muy buena nota, transmite su pasión por el teatro y la contagia, como dijeron abajo, debes estar listo para actuar y dejar la pena o ansiedad de lado. Solo prepare con tiempo el guion del proyecto final y tenga una buena idea. Matricule con ella sin dudar.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Respetado por los estudiantes']::TEXT[], '2022-11-17T00:00:00+00:00'::TIMESTAMPTZ, '6651a6c44584a396a332a42d5f923d6227a0a1c7ffcac565d338b54419e8c785'::TEXT, ARRAY[498]::BIGINT[]),
    (167::BIGINT, 'Excelente. Preparese para participar, nadie se escapa. Hay que saber editar imágenes, audio, video, etc. Es una clase entretenida, se nota que le apasiona su trabajo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2022-07-19T00:00:00+00:00'::TIMESTAMPTZ, '7fbc4fec38d50f0a34e0438532ce752de6279cede7b6b95af49e5577a6d47787'::TEXT, ARRAY[498]::BIGINT[]),
    (167::BIGINT, 'La profesora califica bien, eso sí espera un trabajo de calidad y debe de tener en cuenta que deberá aprender a editar o hacer equipo con alguien que sepa, para poder entregar algo decente y pasar bien. A veces se ponía a fumar y tomar en clases, es muy relajada y todo le parece una buena actuación.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-02-25T00:00:00+00:00'::TIMESTAMPTZ, 'b8e9e1ec6b41d5c564420f570fb4331fe04e71bf05a8da70775d94e6954bfa68'::TEXT, ARRAY[498]::BIGINT[]),
    (167::BIGINT, 'Es una profesora agradable, da muy buena retroalimentación y le apasiona bastante el teatro. El problema es que a la hora de dar notas parece bajar puntos solo por que sí, a pesar de que en el momento le haya parecido excelente la actuación.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2021-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'a5aab40d887274b178a8fd5f7cbf405a6f7a5a5c2b7edadeb6d2869b7c5d21fa'::TEXT, ARRAY[692]::BIGINT[]),
    (167::BIGINT, 'Es una profe que se nota que le gusta lo que enseña, si usted tiene interés en el teatro y no le da vergüenza nada, matricule el cultural con ella. Hay que poner la camára en todas las clases. Es muy fácil pasar, pero tiene que hacer todas las tareas y enviarlas a tiempo.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Inspirador', 'Brinda apoyo']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, 'ae13568913246cc7bcd9e8b9d5fca61299effe53869e98110ee33115119d4dc2'::TEXT, ARRAY[498]::BIGINT[]),
    (167::BIGINT, 'Es un excelente curso, se debe prender mucho la cámara y hacer exámenes grupales, busque gente que se comprometa con el trabajo y madurez necesaria. Diviértase mucho, en la virtualidad es una salvada para salir de la cultural que le falte!;)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Clases excelentes']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, 'e08d83dbcb3a89b2485f35b1f274acf4a032d24cee58e9bdf8c9e13f6da434ff'::TEXT, ARRAY[498]::BIGINT[]),
    (167::BIGINT, 'Es bastante apasionada a la hora de dar la clase, deja trabajos bastante sencillos y es bastante fácil pasar el curso, además de que es bastante divertido. Es necesario estar poniendo la cámara para los ejercicios en clases.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Brinda apoyo']::TEXT[], '2021-06-26T00:00:00+00:00'::TIMESTAMPTZ, '305d9c4083ca696618a5f317ec44fda46ab4766b8d32cefd2bf74ebe8569ad38'::TEXT, ARRAY[498]::BIGINT[]),
    (167::BIGINT, '¡Excelente profe! Se nota que ama el teatro, si quieren matricular en artes dramáticas, ella es la mejor opción.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-06-23T00:00:00+00:00'::TIMESTAMPTZ, '264208c6e183e294dd8173bf655709fa0a6765e6006131f523ba83aef48e8dd2'::TEXT, ARRAY[498]::BIGINT[]),
    (167::BIGINT, 'Muy buena profe, pero si usted tiene problemas de ansiedad social, no matricule con ella a menos que este dispuest@ a enfrentar esa ansiedad, en virtual pide camara, y si no tiene camara le toca grabarlo para subirlo despues. Tiene que estar dispuesto a quitarse la ansiedad si matricula con ella.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2021-03-03T00:00:00+00:00'::TIMESTAMPTZ, 'f68c670dbcde14c7deb27786afe4e268bfd9ff5668cd88956ee2d570e60cbbcb'::TEXT, ARRAY[498]::BIGINT[]),
    (167::BIGINT, 'Excelente profe, se nota que le apasiona lo que hace, el curso es completamente disfrutable.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases largas', 'Clases excelentes']::TEXT[], '2021-02-02T00:00:00+00:00'::TIMESTAMPTZ, '3a42902bd8177034c0637d3fcbe226c8d7e0ce96d5e33be0bc7d58ef143a7859'::TEXT, ARRAY[498]::BIGINT[]),
    (167::BIGINT, 'Es una excelente profesora, las clases son divertidas e interesantes, los asistentes siempre están ahí dispuestos a ayudar. Eso sí, tiene que participar y poner atención en todo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2021-01-26T00:00:00+00:00'::TIMESTAMPTZ, '3e571fa85f3132f9a48c3fe905e77044a82eac1dc00dd564c7946dd98e918007'::TEXT, ARRAY[498]::BIGINT[]),
    (167::BIGINT, 'La profe es excelente, uno disfruta bastante... Se adapto a la nueva modalidad.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, '5a2af2e1a8f0c55e9c2d0d8dd055589241c2e3de7471bac11c7d832eb95f39cb'::TEXT, ARRAY[498]::BIGINT[]),
    (167::BIGINT, 'Se adaptó a la nueva forma, mandó cosas simples para hacer en la casa, muy buena gente'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'cc3928bbefdd96c15e2089d3227e8700d633a83ed79d5bc0c6c9d3f189f05913'::TEXT, ARRAY[498]::BIGINT[]),
    (167::BIGINT, 'Tomar la cultural de artes dramáticas con Alexandra es una aventura, especial para salir de la zona de confort y experimentar nuevas cosas. En la modalidad virtual logró modificar excelente su metodología de enseñanza. No obstante hay que sacar tiempo para realizar sus tareas.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Inspirador', 'Clases excelentes']::TEXT[], '2020-08-04T00:00:00+00:00'::TIMESTAMPTZ, 'fb0b329109cd37630026b0503f3e5b2fbd978a22ffdb0f9e4700637f77b4e60e'::TEXT, ARRAY[498]::BIGINT[]),
    (167::BIGINT, 'Excelente, es demasiado linda como persona. Las clases son vacilonas, como para pasar el rato, conocer gente, hacer estúpido. Le pone para la presentación final, pero durante el semestre es muy al suave y nunca exige'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes']::TEXT[], '2020-02-05T00:00:00+00:00'::TIMESTAMPTZ, '67b9048b86cd6f15dbf55048e0e46dbcaf36809e99a2874b9a6ce90a75ff4f00'::TEXT, ARRAY[498]::BIGINT[]),
    (167::BIGINT, 'Nada fuera de lo normal para ser una cultural, a final de semestre corre mucho con la obra final.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, '7a2b9fb30cc13d3add69691caa4b6c75e661f47cb2892d6546024d8df92959ba'::TEXT, ARRAY[498]::BIGINT[]),
    (167::BIGINT, 'Espera que la gente sepa actuar, la participación no la toma en cuenta e impone sus ideas sobre la de los estudiantes, preferencias claras, la obra final se hace a la carrera. Si lo lleva con ella intenta caerle bien o si no la va a tener dificil'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-02T00:00:00+00:00'::TIMESTAMPTZ, '92c7c782fbefb3cbfd974edab2407ea9638b2d92469bf9b2daad35226ab37ced'::TEXT, ARRAY[498]::BIGINT[]),
    (167::BIGINT, 'Buenísima, la mejor para artes dramáticas creo yo. A pesar de que tuvimos que correr un toque con la obra final, todo salió super bien. Se disfrutan las clases y es muy divertido, con solo ir a clase y participar tiene el curso ganado.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'bafeb3613e9d377ab2b75efcbe3e05d461ec1e71ab4820523132e118a52116fa'::TEXT, ARRAY[498]::BIGINT[]),
    (167::BIGINT, 'La profe es súper buena nota, casi todas las semanas hay tareas, pero son fáciles y rápidas. Le encanta el teatro y hace que a usted también le termine gustando. Es muy fácil pasar este curso con buena nota, sin embargo para el examen final no queda mucho tiempo para prepararlo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'c0e8e61c7d6f8f72ca929c46d32684d33b5b2bb3cff39a83efb423063f598e3a'::TEXT, ARRAY[498]::BIGINT[]),
    (167::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2017-06-28T00:00:00+00:00'::TIMESTAMPTZ, '0303f9f2938434362e9890e0ec20161f60d75d3b3731d910ff8faad64841d70f'::TEXT, ARRAY[498]::BIGINT[]),
    (167::BIGINT, 'No me agradó llevar el curso con ella. Las clases son muy teóricas y la parte de actuación empieza como a medio semestre. Realmente califica su actuación, no la participación. Además la organización del tiempo no fue buena y la obra final la pudimos planear apenas en 2 lecciones.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Aspectos de calificación claros', 'Muchos proyectos grupales']::TEXT[], '2017-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'adeffb88273cee177663dcd54841dd9cbda938f1bbf5cef146f190948309c095'::TEXT, ARRAY[498]::BIGINT[]),
    (167::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'e11ecca7c07766aa6c7a24fa8b72d2bcc07ba175f255ad05b7799605b40e5635'::TEXT, ARRAY[498]::BIGINT[]),
    (167::BIGINT, 'Le encanta dar su curso. Buen humor siempre. Es entretenido. Si a usted le gusta teatro el curso le encantará, sino le gusta teatro le terminará gustando.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-07-01T00:00:00+00:00'::TIMESTAMPTZ, 'eae34a444ded4e8a0247247bdb7838c8cd4c31caa4cc966832c3e3ee3cbd01ba'::TEXT, ARRAY[498]::BIGINT[]),
    (167::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-29T00:00:00+00:00'::TIMESTAMPTZ, '3d7290e4953dd57c0a6e6ee462b23f2df70e52bb4758e05d0879162729cdae54'::TEXT, ARRAY[506]::BIGINT[]),
    (167::BIGINT, 'Ama lo que hace y por eso es tan buena profe. Recomendadisima'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-23T00:00:00+00:00'::TIMESTAMPTZ, '56e9734b2cf9b2c50a18145c60db183143e7edaeabc95945509498eef505941a'::TEXT, ARRAY[498]::BIGINT[]),
    (167::BIGINT, 'Llevé artes dramáticas con ella... sin duda el mejor curso del TEC, de hecho me enamore del teatro por culpa de ella, es un curso al que ud va a querer llegar!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-22T00:00:00+00:00'::TIMESTAMPTZ, '6da1d70aa531d5a31bc33e7c16f5e88877e4e74c23a0419ce901231e3185130b'::TEXT, ARRAY[498]::BIGINT[]),
    (167::BIGINT, 'Muy buena profe! Aunque en la obra del proyecto final grita mucho. Evalúa muy fácil y es casi imposible que alguien se quede.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-16T00:00:00+00:00'::TIMESTAMPTZ, '1150eabb9c4a8a17c40cba1b45e4b744dcaa76848caca94a374d49fa86a2f2e1'::TEXT, ARRAY[498]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
